calc.mjs.text:
/**
 * KDP / Kindle Unlimited / wide-distribution royalty arithmetic.
 *
 * Every rate is an input the author overwrites from their own KDP dashboard
 * or Ingram quote. The defaults are published starting points, not a live
 * Amazon schedule, and they are labelled that way on the page.
 */

const finite = (value, name) => {
  const number = Number(value);
  if (!Number.isFinite(number) || number < 0) {
    throw new Error(`${name} must be a non-negative number`);
  }
  return number;
};

const optional = (value, name, fallback) => {
  if (value === '' || value === undefined || value === null) return fallback;
  return finite(value, name);
};

export const DEFAULTS = Object.freeze({
  ebookList: 4.99,
  ebookPlan: '70',
  fileSizeMb: 2,
  deliveryPerMb: 0.15,
  ebookPaidSales: 80,
  kenpReads: 12000,
  kenpRate: 0.0045,
  paperbackList: 14.99,
  paperbackPages: 280,
  paperbackColor: false,
  paperbackPrintOverride: '',
  paperbackSales: 20,
  paperbackRoyaltyRate: 0.6,
  otherStoreSales: 40,
  otherStoreNet: 2.5,
  ingramSales: 10,
  ingramWholesale: 0.4,
  ingramPrintCost: 5,
  bwFixed: 0.85,
  bwPerPage: 0.012,
  colorFixed: 0.85,
  colorPerPage: 0.07,
});

/**
 * Every id the form owns, in the order the page presents them.
 *
 * This is a strict subset of `DEFAULTS`: the five print-schedule constants
 * (`paperbackRoyaltyRate`, `bwFixed`, `bwPerPage`, `colorFixed`,
 * `colorPerPage`) are inputs to the arithmetic but not controls on the page,
 * so `Object.keys(DEFAULTS)` is not the list a form-reading caller wants.
 *
 * It lives here rather than in `index.html`, where it used to be restated
 * inline, because two callers now need the same list and a copied rule is
 * how this repository has twice shipped live defects — see CLAUDE.md, "168
 * became 169". `share.test.mjs` asserts the page imports it instead of
 * declaring its own.
 */
export const FORM_FIELD_IDS = Object.freeze([
  'ebookList', 'ebookPlan', 'fileSizeMb', 'deliveryPerMb', 'ebookPaidSales',
  'kenpReads', 'kenpRate', 'paperbackList', 'paperbackPages', 'paperbackColor',
  'paperbackPrintOverride', 'paperbackSales', 'otherStoreSales', 'otherStoreNet',
  'ingramSales', 'ingramWholesale', 'ingramPrintCost',
]);

/**
 * The two controls that are a choice rather than a number, with the exact
 * option values their `<select>` offers.
 *
 * A shared link must not be able to put a value in one of these that the
 * form cannot represent: assigning an unknown value to a `<select>` leaves
 * the previous selection standing, silently, so the recipient would compute
 * a 70%-plan royalty from a link that said 35%.
 */
export const SELECT_OPTIONS = Object.freeze({
  ebookPlan: Object.freeze(['70', '35']),
  paperbackColor: Object.freeze(['false', 'true']),
});

/** Form fields that carry a number. Everything that is not a `<select>`. */
export const NUMERIC_FIELD_IDS = Object.freeze(
  FORM_FIELD_IDS.filter((id) => !(id in SELECT_OPTIONS)),
);

/** The one numeric field the form lets an author leave blank: blank means
 * "derive the print cost from the page count" rather than "costs nothing". */
export const OPTIONAL_FIELD_IDS = Object.freeze(['paperbackPrintOverride']);

export function printCost({ pages, color, override, bwFixed, bwPerPage, colorFixed, colorPerPage }) {
  if (override !== '' && override !== undefined && override !== null) {
    return finite(override, 'Paperback print cost');
  }
  const count = finite(pages, 'Paperback pages');
  if (color) {
    return finite(colorFixed, 'Color fixed print cost') + finite(colorPerPage, 'Color per-page print cost') * count;
  }
  return finite(bwFixed, 'B&W fixed print cost') + finite(bwPerPage, 'B&W per-page print cost') * count;
}

export function ebookNet({ list, plan, fileSizeMb, deliveryPerMb }) {
  const price = finite(list, 'eBook list price');
  const size = finite(fileSizeMb, 'File size');
  const perMb = finite(deliveryPerMb, 'Delivery cost per MB');
  if (plan === '35') return price * 0.35;
  if (plan !== '70') throw new Error('eBook royalty plan must be 70 or 35');
  return price * 0.7 - size * perMb;
}

export function paperbackNet({ list, royaltyRate, print }) {
  const price = finite(list, 'Paperback list price');
  const rate = finite(royaltyRate, 'Paperback royalty rate');
  if (rate > 1) throw new Error('Paperback royalty rate must be a fraction of list (0–1), not a percent');
  return price * rate - finite(print, 'Paperback print cost');
}

export function ingramNet({ list, wholesale, print }) {
  const price = finite(list, 'Paperback list price');
  const discount = finite(wholesale, 'Ingram wholesale discount');
  if (discount > 1) throw new Error('Ingram wholesale discount must be a fraction of list (0–1), not a percent');
  return price * (1 - discount) - finite(print, 'Ingram print cost');
}

export function seventyPercentEligible(list) {
  const price = finite(list, 'eBook list price');
  return price >= 2.99 && price <= 9.99;
}

/**
 * One 90-day window on the same book: KDP exclusive (paid sales + KU + KDP
 * paperback) versus going wide (same KDP paid sales, no KU, plus other-store
 * ebook volume and Ingram paperbacks).
 */
export function compareExclusiveVsWide(input) {
  const ebookList = optional(input.ebookList, 'eBook list price', DEFAULTS.ebookList);
  const ebookPlan = String(input.ebookPlan ?? DEFAULTS.ebookPlan);
  const fileSizeMb = optional(input.fileSizeMb, 'File size', DEFAULTS.fileSizeMb);
  const deliveryPerMb = optional(input.deliveryPerMb, 'Delivery cost per MB', DEFAULTS.deliveryPerMb);
  const ebookPaidSales = optional(input.ebookPaidSales, 'eBook paid sales', DEFAULTS.ebookPaidSales);
  const kenpReads = optional(input.kenpReads, 'KU page reads', DEFAULTS.kenpReads);
  const kenpRate = optional(input.kenpRate, 'KENP rate', DEFAULTS.kenpRate);
  const paperbackList = optional(input.paperbackList, 'Paperback list price', DEFAULTS.paperbackList);
  const paperbackPages = optional(input.paperbackPages, 'Paperback pages', DEFAULTS.paperbackPages);
  const paperbackColor = Boolean(input.paperbackColor);
  const paperbackPrintOverride = input.paperbackPrintOverride ?? DEFAULTS.paperbackPrintOverride;
  const paperbackSales = optional(input.paperbackSales, 'Paperback sales', DEFAULTS.paperbackSales);
  const paperbackRoyaltyRate = optional(
    input.paperbackRoyaltyRate,
    'Paperback royalty rate',
    DEFAULTS.paperbackRoyaltyRate,
  );
  const otherStoreSales = optional(input.otherStoreSales, 'Other-store ebook sales', DEFAULTS.otherStoreSales);
  const otherStoreNet = optional(input.otherStoreNet, 'Other-store net per sale', DEFAULTS.otherStoreNet);
  const ingramSales = optional(input.ingramSales, 'Ingram paperback sales', DEFAULTS.ingramSales);
  const ingramWholesale = optional(input.ingramWholesale, 'Ingram wholesale discount', DEFAULTS.ingramWholesale);
  const ingramPrintCost = optional(input.ingramPrintCost, 'Ingram print cost', DEFAULTS.ingramPrintCost);
  const bwFixed = optional(input.bwFixed, 'B&W fixed print cost', DEFAULTS.bwFixed);
  const bwPerPage = optional(input.bwPerPage, 'B&W per-page print cost', DEFAULTS.bwPerPage);
  const colorFixed = optional(input.colorFixed, 'Color fixed print cost', DEFAULTS.colorFixed);
  const colorPerPage = optional(input.colorPerPage, 'Color per-page print cost', DEFAULTS.colorPerPage);

  const unitEbook = ebookNet({ list: ebookList, plan: ebookPlan, fileSizeMb, deliveryPerMb });
  const kdpPrint = printCost({
    pages: paperbackPages,
    color: paperbackColor,
    override: paperbackPrintOverride,
    bwFixed,
    bwPerPage,
    colorFixed,
    colorPerPage,
  });
  const unitPaperback = paperbackNet({
    list: paperbackList,
    royaltyRate: paperbackRoyaltyRate,
    print: kdpPrint,
  });
  const unitIngram = ingramNet({
    list: paperbackList,
    wholesale: ingramWholesale,
    print: ingramPrintCost,
  });

  const ebookPaid = ebookPaidSales * unitEbook;
  const ku = kenpReads * kenpRate;
  const paperback = paperbackSales * unitPaperback;
  const otherStores = otherStoreSales * otherStoreNet;
  const ingram = ingramSales * unitIngram;

  const exclusiveWithoutKu = ebookPaid + paperback;
  const exclusive = exclusiveWithoutKu + ku;
  const wide = ebookPaid + paperback + otherStores + ingram;
  const wideExtras = otherStores + ingram;
  const exclusiveWins = exclusive > wide;
  const gap = exclusive - wide;

  const pagesToMatchOneSale = kenpRate > 0 && unitEbook > 0 ? unitEbook / kenpRate : Infinity;
  const readsToMatchWide = kenpRate > 0 && wideExtras > 0 ? wideExtras / kenpRate : 0;

  return {
    unitEbook,
    unitPaperback,
    unitIngram,
    kdpPrint,
    ebookPaid,
    ku,
    paperback,
    otherStores,
    ingram,
    exclusive,
    wide,
    exclusiveWithoutKu,
    wideExtras,
    exclusiveWins,
    gap,
    pagesToMatchOneSale,
    readsToMatchWide,
    seventyEligible: seventyPercentEligible(ebookList),
    usedSeventy: ebookPlan === '70',
  };
}

export function exclusiveNote(result) {
  const money = (n) => {
    const format = (n) => `$${n.toFixed(2)}`;
    const text = format(Math.abs(n));
    return n < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  if (result.wideExtras === 0 && result.ku === 0) {
    return `With no KU reads and no wide extras, both paths keep ${money(result.exclusive)} — the paid KDP sales alone.`;
  }
  if (result.exclusiveWins) {
    return `Exclusive keeps ${money(result.exclusive)} against ${money(result.wide)} wide, ahead by ${money(result.gap)}. KU page-reads are doing the extra work.`;
  }
  return `Wide keeps ${money(result.wide)} against ${money(result.exclusive)} exclusive, ahead by ${money(-result.gap)}. Other-store and Ingram volume is larger than this KU window.`;
}

share.mjs.text:
// Send a whole exclusive-versus-wide comparison to the other person on the book.
//
// This page decides one thing — whether KDP Select is ahead of going wide for
// *this* title — and it takes seventeen inputs to decide it: two list prices,
// a page count, a royalty plan, a KENP rate, and unit economics for four
// separate sales channels. That decision is almost never made alone. A
// co-author, an editor, a small press, or the author's own other device all
// need to see the same seventeen numbers to disagree usefully about them, and
// today the only way to move them is to read them out.
//
// So the comparison travels in a link, built and copied in the reader's own
// browser. The figures ride in the URL *fragment* (`#...`), never the query
// string: a fragment is not sent in the request line a server logs, nor in
// the `Referer` header a later click carries.
//
// (Unlike `shop-rate-calculator`, which deliberately refuses to put a shop's
// payroll in a URL and should keep refusing, everything here is a list price,
// a page count, or a royalty rate off a public schedule. The list prices are
// already printed on the book's own store page.)
//
// ## Two selects, and why they are not just strings
//
// `ebookPlan` and `paperbackColor` are choices, not numbers. Assigning an
// unrecognised value to a `<select>` does not throw and does not clear it —
// it leaves the previous selection standing. So a link carrying
// `ebookPlan=50` would silently compute a 70%-plan royalty while the sender
// believed they had sent a different plan, which is the same
// silent-divergence defect this portfolio's `share.mjs` shipped once already
// (a link that dropped `quantity` and `targetMargin`, so the recipient
// computed a different profit than the sender saw). `decodeInputs` therefore
// validates both against the option lists `calc.mjs` publishes, and drops
// anything else.
//
// The field list, the option lists, and which field may be blank are all
// imported from `calc.mjs` rather than restated here — see the note on
// `FORM_FIELD_IDS` there.

import {
  FORM_FIELD_IDS,
  NUMERIC_FIELD_IDS,
  OPTIONAL_FIELD_IDS,
  SELECT_OPTIONS,
} from './calc.mjs';

export const FIELD_IDS = FORM_FIELD_IDS;

function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  if (String(value).trim() === '') return null;
  const result = Number(value);
  return Number.isFinite(result) && result >= 0 ? result : null;
}

/** The value to put in a link for one field, or `null` to leave it out. */
function encodeField(id, value) {
  if (id in SELECT_OPTIONS) {
    const text = String(value ?? '');
    return SELECT_OPTIONS[id].includes(text) ? text : null;
  }
  const number = usableNumber(value);
  return number === null ? null : String(number);
}

/** The value to accept from a link for one field, or `null` to ignore it. */
function decodeField(id, value) {
  return encodeField(id, value);
}

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const id of FIELD_IDS) {
    const encoded = encodeField(id, input?.[id]);
    if (encoded !== null) params.set(id, encoded);
  }
  return params.toString();
}

export function decodeInputs(source) {
  const params = new URLSearchParams(String(source || '').replace(/^[?#]/, ''));
  const result = {};
  for (const id of FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = decodeField(id, params.get(id));
    if (value !== null) result[id] = value;
  }
  return result;
}

/** Whether a link carried anything at all. */
export function hasSharedInputs(decoded) {
  return Object.keys(decoded || {}).length > 0;
}

/**
 * Every field the form owns, as the string a control holds — the shared value
 * where the link had one, and `''` where it did not.
 *
 * The clearing is the part that matters, and it is why callers should use
 * this rather than writing the decoded object onto the form directly.
 * `paperbackPrintOverride` may legitimately be blank, meaning "derive the
 * print cost from the page count"; a sender who left it blank and a
 * recipient whose form still held their own override would be comparing two
 * different books. Selects are the exception — a `<select>` cannot hold `''`
 * when that is not one of its options, so an absent choice falls back to the
 * option the form ships selected rather than to an empty string.
 */
export function formValues(decoded) {
  const source = decoded || {};
  return Object.fromEntries(
    FIELD_IDS.map((id) => {
      if (id in source) return [id, String(source[id])];
      if (id in SELECT_OPTIONS) return [id, SELECT_OPTIONS[id][0]];
      return [id, ''];
    }),
  );
}

export { NUMERIC_FIELD_IDS, OPTIONAL_FIELD_IDS, SELECT_OPTIONS };

usage.mjs.text:
const KEY = 'kdp-royalty-calculator-usage-v1';

function honorsBrowserSignal() {
  try {
    return (
      globalThis.navigator?.doNotTrack === '1' ||
      globalThis.window?.doNotTrack === '1' ||
      globalThis.navigator?.globalPrivacyControl === true
    );
  } catch {
    return false;
  }
}

export function recordUsage(event, optedOut = false, storage = globalThis.localStorage) {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const entries = JSON.parse(storage.getItem(KEY) || '{}');
    const day = new Date().toISOString().slice(0, 10);
    entries[`${event}:${day}`] = (entries[`${event}:${day}`] || 0) + 1;
    storage.setItem(KEY, JSON.stringify(entries));
  } catch {
    /* Calculator remains useful when storage is unavailable. */
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
